import React, { useContext, useEffect, useState } from "react";
import { useNavigate } from "react-router-dom";
import Sidebar from "../components/Sidebar";
import axiosInstance from "../api/axios";
import { AuthContext } from "../context/AuthContext";
import "../global.css";

export default function StudentProfile() {
  const { user, logout } = useContext(AuthContext);
  const navigate = useNavigate();

  const [marks, setMarks] = useState([]); // raw list of marks
  const [loading, setLoading] = useState(false);
  const [error, setError] = useState("");

  useEffect(() => {
    const load = async () => {
      if (!user?.id && !user?._id) return;
      setError("");
      setLoading(true);
      try {
        const res = await axiosInstance.get('/marks', { params: { studentId: user.id || user._id } });
        setMarks(Array.isArray(res.data) ? res.data : []);
      } catch (e) {
        setError(e.response?.data?.message || 'Failed to load marks');
        setMarks([]);
      } finally {
        setLoading(false);
      }
    };
    load();
  }, [user]);

  const onLogout = () => {
    logout();
    navigate('/login');
  };

  return (
    <div className="dashboard-flex">
      <Sidebar />
      <div className="dashboard-main">
        <header className="dashboard-header-row">
          <div>
            <h1 className="dashboard-title">Profile</h1>
            <p className="dashboard-subtitle">Your profile details and marks.</p>
          </div>
          <div className="header-actions">
            <button className="signout-btn" onClick={onLogout}>Logout</button>
          </div>
        </header>

        {/* Profile card */}
        <section className="profile-card">
          <div className="header-profile-chip" style={{ marginBottom: 16 }}>
            <div className="chip-avatar">{(user?.name || 'S')[0]}</div>
            <div className="chip-info">
              <span className="chip-name">{user?.name || '-'}</span>
              <span className="chip-role">Student</span>
            </div>
          </div>
          <div className="profile-fields">
            <div><strong>Name:</strong> {user?.name || '-'}</div>
            <div><strong>Email:</strong> {user?.email || '-'}</div>
            <div><strong>USN:</strong> {user?.usn || '-'}</div>
            <div><strong>Year:</strong> {user?.year || '-'}</div>
            <div><strong>Department:</strong> {user?.department || '-'}</div>
            <div><strong>Class:</strong> {user?.class || '-'}</div>
            <div><strong>Section:</strong> {user?.section || '-'}</div>
          </div>
        </section>

        {/* Marks table */}
        <section className="entermarks-table-block" style={{ marginTop: 16 }}>
          {error && <div className="error-message" style={{ margin: '8px 0' }}>{error}</div>}
          {loading && <div className="muted">Loading marks...</div>}
          <table className="entermarks-table">
            <thead>
              <tr>
                <th>Subject</th>
                <th>Category</th>
                <th>Marks</th>
              </tr>
            </thead>
            <tbody>
              {marks.map(m => (
                <tr key={m._id}>
                  <td><i className="fa-solid fa-book-open" style={{ marginRight: 6 }} />{m.subject}</td>
                  <td>{m.category}</td>
                  <td>{m.marks}</td>
                </tr>
              ))}
              {marks.length===0 && !loading && (
                <tr><td colSpan={3} className="muted" style={{textAlign:'center'}}>No marks yet</td></tr>
              )}
            </tbody>
          </table>
        </section>
      </div>
    </div>
  );
}
